const solicitud = $input.first().json;

return [{
  json: {
    headers: {
      authorization:
        typeof solicitud.headers?.authorization === 'string'
          ? solicitud.headers.authorization
          : '',
    },
  },
}];

const autenticacion = $input.first().json;

if (![200, 401, 503].includes(autenticacion.status_http)) {
  throw new Error('Respuesta de autenticación inesperada.');
}

if (autenticacion.status_http !== 200) {
  return [{
    json: {
      continuar: false,
      status_http: autenticacion.status_http,
      respuesta: autenticacion.respuesta,
    },
  }];
}

const usuario = autenticacion.respuesta?.data?.usuario;

if (
  autenticacion.respuesta?.ok !== true ||
  typeof usuario?.usuario_id !== 'string' ||
  !usuario.usuario_id.trim()
) {
  throw new Error('No se recibió un usuario autenticado válido.');
}

const solicitud =
  $('Webhook - Crear inscripción').first().json;

const contentType = String(
  solicitud.headers?.['content-type'] ?? ''
)
  .split(';')[0]
  .trim()
  .toLowerCase();

function rechazar(status, mensaje) {
  return [{
    json: {
      continuar: false,
      status_http: status,
      respuesta: {
        ok: false,
        error: {
          codigo: 'SOLICITUD_INSCRIPCION_INVALIDA',
          mensaje,
        },
      },
    },
  }];
}

if (contentType !== 'application/json') {
  return rechazar(415, 'Envía los datos como application/json.');
}

const cuerpo = solicitud.body;

if (
  cuerpo === null ||
  typeof cuerpo !== 'object' ||
  Array.isArray(cuerpo)
) {
  return rechazar(400, 'El cuerpo debe ser un objeto JSON.');
}

const permitidos = [
  'evento_id',
  'nombre_acreditacion',
  'observaciones',
];

if (Object.keys(cuerpo).some(campo => !permitidos.includes(campo))) {
  return rechazar(400, 'La solicitud contiene campos no permitidos.');
}

if (
  typeof cuerpo.evento_id !== 'string' ||
  typeof cuerpo.nombre_acreditacion !== 'string' ||
  (
    cuerpo.observaciones !== undefined &&
    typeof cuerpo.observaciones !== 'string'
  )
) {
  return rechazar(400, 'Los campos deben contener texto.');
}

const eventoId = cuerpo.evento_id.trim();
const nombre = cuerpo.nombre_acreditacion.trim();
const observaciones = (cuerpo.observaciones ?? '').trim();

if (!/^EVT-[A-Za-z0-9_-]{1,76}$/.test(eventoId)) {
  return rechazar(400, 'El identificador del evento no es válido.');
}

const caracteresControl = /[\u0000-\u001F\u007F]/;

if (
  [...nombre].length < 2 ||
  [...nombre].length > 100 ||
  caracteresControl.test(nombre)
) {
  return rechazar(
    400,
    'El nombre de acreditación debe tener entre 2 y 100 caracteres y no contener caracteres de control.'
  );
}

if (
  [...observaciones].length > 500 ||
  caracteresControl.test(observaciones)
) {
  return rechazar(
    400,
    'Las observaciones deben tener como máximo 500 caracteres y escribirse en una sola línea.'
  );
}

return [{
  json: {
    continuar: true,
    datos: {
      usuario_id: usuario.usuario_id,
      evento_id: eventoId,
      nombre_acreditacion: nombre,
      observaciones,
      origen: 'WEB',
    },

    // Respuesta temporal para probar únicamente esta etapa.
    status_http: 200,
    respuesta: {
      ok: true,
      mensaje: 'Solicitud validada. Todavía no se ha creado una inscripción.',
      data: {
        evento_id: eventoId,
      },
    },
  },
}];

