const solicitud =
  $('Validar solicitud de inscripción').first().json;

if (
  solicitud.continuar !== true ||
  typeof solicitud.datos?.usuario_id !== 'string' ||
  !solicitud.datos.usuario_id
) {
  throw new Error('No se recibió una solicitud autenticada válida.');
}

const filas = $input.all()
  .map(item => item.json)
  .filter(fila => Object.keys(fila).length > 0);

const identificadores = new Set();

for (const fila of filas) {
  if (
    fila.usuario_id !== solicitud.datos.usuario_id ||
    typeof fila.vinculacion_id !== 'string' ||
    !fila.vinculacion_id.trim() ||
    !['ACTIVA', 'INACTIVA'].includes(fila.estado)
  ) {
    throw new Error('La vinculación contiene datos inconsistentes.');
  }

  if (identificadores.has(fila.vinculacion_id)) {
    throw new Error('Hay identificadores de vinculación duplicados.');
  }

  identificadores.add(fila.vinculacion_id);
}

const activas = filas.filter(fila => fila.estado === 'ACTIVA');

if (activas.length > 1) {
  throw new Error('El usuario tiene varias vinculaciones activas.');
}

if (activas.length === 0) {
  return [{
    json: {
      continuar: false,
      status_http: 403,
      respuesta: {
        ok: false,
        error: {
          codigo: 'TELEGRAM_REQUERIDO',
          mensaje:
            'Vincula tu cuenta de Telegram antes de inscribirte en un evento.',
        },
      },
    },
  }];
}

const vinculacion = activas[0];
const chatId = String(vinculacion.chat_id ?? '').trim();

if (
  !/^[1-9]\d*$/.test(chatId) ||
  !Number.isFinite(Date.parse(vinculacion.fecha_vinculacion))
) {
  throw new Error('La vinculación activa está incompleta.');
}

return [{
  json: {
    continuar: true,
    datos: solicitud.datos,

    // Datos internos para los siguientes pasos.
    telegram: {
      vinculacion_id: vinculacion.vinculacion_id,
      chat_id: chatId,
    },

    // Respuesta temporal; todavía no consultamos el evento.
    status_http: 200,
    respuesta: {
      ok: true,
      mensaje:
        'Solicitud y Telegram validados. Todavía no se ha creado una inscripción.',
      data: {
        evento_id: solicitud.datos.evento_id,
      },
    },
  },
}];

const contexto = $('Validar Telegram para inscripción').first().json;

if (
  contexto.continuar !== true ||
  !contexto.datos?.usuario_id ||
  !contexto.datos?.evento_id ||
  !contexto.telegram?.vinculacion_id
) {
  throw new Error('Contexto de inscripción incompleto.');
}

function rechazar(status, codigo, mensaje) {
  return [{
    json: {
      continuar: false,
      status_http: status,
      respuesta: {
        ok: false,
        error: { codigo, mensaje },
      },
    },
  }];
}

const filas = $input.all()
  .map(item => item.json)
  .filter(fila => fila && Object.keys(fila).length > 0);

if (filas.length === 0) {
  return rechazar(
    404,
    'EVENTO_NO_ENCONTRADO',
    'No se encontró el evento solicitado.'
  );
}

if (filas.length !== 1) {
  throw new Error('Se encontraron registros duplicados del evento.');
}

const evento = filas[0];
const eventoId = String(evento.evento_id ?? '').trim();

if (eventoId !== contexto.datos.evento_id) {
  throw new Error('La consulta devolvió un evento diferente.');
}

const estado = String(evento.estado ?? '').trim();
const estadosValidos = [
  'BORRADOR',
  'PUBLICADO',
  'CERRADO',
  'CANCELADO',
];

if (!estadosValidos.includes(estado)) {
  throw new Error('El evento contiene un estado inválido.');
}

if (estado !== 'PUBLICADO') {
  return rechazar(
    409,
    'EVENTO_NO_DISPONIBLE',
    'El evento no está disponible para inscripciones.'
  );
}

const fecha = String(evento.fecha ?? '').trim();
const hora = String(evento.hora ?? '').trim();

if (
  !/^\d{4}-\d{2}-\d{2}$/.test(fecha) ||
  !/^(?:[01]\d|2[0-3]):[0-5]\d$/.test(hora)
) {
  throw new Error('La fecha o la hora del evento tiene un formato inválido.');
}

const [anio, mes, dia] = fecha.split('-').map(Number);
const comprobacion = new Date(`${fecha}T00:00:00Z`);

if (
  !Number.isFinite(comprobacion.getTime()) ||
  comprobacion.getUTCFullYear() !== anio ||
  comprobacion.getUTCMonth() + 1 !== mes ||
  comprobacion.getUTCDate() !== dia
) {
  throw new Error('La fecha del evento no existe en el calendario.');
}

// Las fechas y horas de los eventos corresponden a Colombia.
const inicioMs = Date.parse(`${fecha}T${hora}:00-05:00`);

if (!Number.isFinite(inicioMs)) {
  throw new Error('No fue posible interpretar el inicio del evento.');
}

if (inicioMs <= Date.now()) {
  return rechazar(
    409,
    'EVENTO_NO_DISPONIBLE',
    'El evento ya comenzó o su fecha ya pasó.'
  );
}

const capacidadTexto = String(evento.capacidad ?? '').trim();

if (!/^\d+$/.test(capacidadTexto)) {
  throw new Error('La capacidad del evento tiene un formato inválido.');
}

const capacidad = Number(capacidadTexto);

if (!Number.isSafeInteger(capacidad) || capacidad < 1) {
  throw new Error('La capacidad del evento debe ser un entero positivo.');
}

return [{
  json: {
    continuar: true,
    datos: contexto.datos,
    telegram: contexto.telegram,
    evento: {
      evento_id: eventoId,
      nombre: String(evento.nombre ?? '').trim(),
      fecha,
      hora,
      estado,
      capacidad,
      inicio_ms: inicioMs,
    },
    status_http: 200,
    respuesta: {
      ok: true,
      mensaje:
        'Solicitud, Telegram y evento validados. Todavía no se ha creado una inscripción.',
      data: {
        evento_id: eventoId,
      },
    },
  },
}];

const contexto = $('Validar evento para inscripción').first().json;

if (
  contexto.continuar !== true ||
  !contexto.datos?.usuario_id ||
  !contexto.datos?.evento_id ||
  contexto.evento?.evento_id !== contexto.datos.evento_id
) {
  throw new Error('Contexto inválido para consultar disponibilidad.');
}

const capacidad = contexto.evento.capacidad;

if (!Number.isSafeInteger(capacidad) || capacidad < 1) {
  throw new Error('La capacidad del evento es inválida.');
}

function rechazar(status, codigo, mensaje) {
  return [{
    json: {
      continuar: false,
      status_http: status,
      respuesta: {
        ok: false,
        error: { codigo, mensaje },
      },
    },
  }];
}

// La lectura puede tardar: comprobamos otra vez el inicio del evento.
if (
  !Number.isFinite(contexto.evento.inicio_ms) ||
  contexto.evento.inicio_ms <= Date.now()
) {
  return rechazar(
    409,
    'EVENTO_NO_DISPONIBLE',
    'El evento ya comenzó o su fecha ya pasó.'
  );
}

const filas = $input.all()
  .map(item => item.json)
  .filter(fila => fila && Object.keys(fila).length > 0);

const registros = [];
const ids = new Set();

for (const fila of filas) {
  // Ignora filas completamente vacías, aunque incluyan row_number.
  const tieneDatos = Object.entries(fila).some(([campo, valor]) =>
    campo !== 'row_number' &&
    valor !== null &&
    valor !== undefined &&
    String(valor).trim() !== ''
  );

  if (!tieneDatos) continue;

  const id = String(fila.inscripcion_id ?? '').trim();
  const usuarioId = String(fila.usuario_id ?? '').trim();
  const eventoId = String(fila.evento_id ?? '').trim();
  const estado = String(fila.estado ?? '').trim();

  if (!id || !usuarioId || !eventoId) {
    throw new Error('Existe una inscripción sin identificadores completos.');
  }

  if (ids.has(id)) {
    throw new Error('Existen identificadores de inscripción duplicados.');
  }

  ids.add(id);

  if (eventoId !== contexto.datos.evento_id) continue;

  if (!['CONFIRMADA', 'LISTA_ESPERA', 'CANCELADA', 'ASISTIO'].includes(estado)) {
    throw new Error('Existe una inscripción del evento con estado desconocido.');
  }

  registros.push({
    inscripcion_id: id,
    usuario_id: usuarioId,
    estado,
  });
}

const activas = registros.filter(registro =>
  ['CONFIRMADA', 'ASISTIO'].includes(registro.estado) ||
  registro.estado === 'LISTA_ESPERA'
);

// Detecta también inconsistencias ya existentes en el evento.
const usuariosActivos = new Set();

for (const registro of activas) {
  if (usuariosActivos.has(registro.usuario_id)) {
    throw new Error('Un usuario tiene varias inscripciones activas en el evento.');
  }

  usuariosActivos.add(registro.usuario_id);
}

if (usuariosActivos.has(contexto.datos.usuario_id)) {
  return rechazar(
    409,
    'INSCRIPCION_DUPLICADA',
    'Ya tienes una inscripción activa en este evento.'
  );
}

const confirmadas = activas.filter(
  registro => ['CONFIRMADA', 'ASISTIO'].includes(registro.estado)
).length;

const enEspera = activas.filter(
  registro => registro.estado === 'LISTA_ESPERA'
).length;

if (confirmadas > capacidad) {
  throw new Error('Las inscripciones confirmadas superan la capacidad.');
}

const cuposDisponibles = capacidad - confirmadas;

// No adelanta a personas que ya están esperando si se liberó un cupo.
const estadoPropuesto = (
  cuposDisponibles > 0 && enEspera === 0
)
  ? 'CONFIRMADA'
  : 'LISTA_ESPERA';

return [{
  json: {
    continuar: true,
    datos: contexto.datos,
    telegram: contexto.telegram,
    evento: contexto.evento,
    disponibilidad: {
      capacidad,
      confirmadas,
      en_espera: enEspera,
      cupos_disponibles: cuposDisponibles,
    },
    estado_propuesto: estadoPropuesto,
    status_http: 200,
    respuesta: {
      ok: true,
      mensaje:
        'Validaciones y disponibilidad comprobadas. Todavía no se ha creado una inscripción.',
      data: {
        evento_id: contexto.datos.evento_id,
        capacidad,
        confirmadas,
        en_espera: enEspera,
        cupos_disponibles: cuposDisponibles,
        estado_propuesto: estadoPropuesto,
      },
    },
  },
}];

const { randomBytes } = require('crypto');

const contexto = $input.first().json;

if (
  contexto.continuar !== true ||
  !contexto.datos?.usuario_id ||
  !contexto.datos?.evento_id ||
  contexto.evento?.evento_id !== contexto.datos.evento_id ||
  !contexto.telegram?.vinculacion_id
) {
  throw new Error('Contexto incompleto para crear la inscripción.');
}

const estado = contexto.estado_propuesto;

if (!['CONFIRMADA', 'LISTA_ESPERA'].includes(estado)) {
  throw new Error('Estado propuesto inválido.');
}

const disponibilidad = contexto.disponibilidad;

if (
  !disponibilidad ||
  !Number.isSafeInteger(disponibilidad.capacidad) ||
  disponibilidad.capacidad < 1 ||
  !Number.isSafeInteger(disponibilidad.confirmadas) ||
  disponibilidad.confirmadas < 0 ||
  disponibilidad.confirmadas > disponibilidad.capacidad ||
  !Number.isSafeInteger(disponibilidad.en_espera) ||
  disponibilidad.en_espera < 0 ||
  disponibilidad.cupos_disponibles !==
    disponibilidad.capacidad - disponibilidad.confirmadas
) {
  throw new Error('Datos de disponibilidad inconsistentes.');
}

const estadoCalculado = (
  disponibilidad.cupos_disponibles > 0 &&
  disponibilidad.en_espera === 0
)
  ? 'CONFIRMADA'
  : 'LISTA_ESPERA';

if (estado !== estadoCalculado) {
  throw new Error('El estado propuesto no coincide con la disponibilidad.');
}

if (!Number.isFinite(contexto.evento.inicio_ms)) {
  throw new Error('Inicio del evento inválido.');
}

if (contexto.evento.inicio_ms <= Date.now()) {
  return [{
    json: {
      continuar: false,
      status_http: 409,
      respuesta: {
        ok: false,
        error: {
          codigo: 'EVENTO_NO_DISPONIBLE',
          mensaje: 'El evento ya comenzó o su fecha ya pasó.',
        },
      },
    },
  }];
}

// Número correlativo de entrada en espera para este evento.
// No representa la posición actual después de cancelaciones.
let ordenEspera = '';

if (estado === 'LISTA_ESPERA') {
  const filas = $('Leer inscripciones para disponibilidad')
    .all()
    .map(item => item.json)
    .filter(fila =>
      String(fila.evento_id ?? '').trim() === contexto.datos.evento_id
    );

  let maximoOrden = 0;

  for (const fila of filas) {
    const valor = String(fila.orden_espera ?? '').trim();

    if (valor === '') {
      if (String(fila.estado ?? '').trim() === 'LISTA_ESPERA') {
        throw new Error('Existe una inscripción en espera sin orden.');
      }
      continue;
    }

    if (!/^[1-9]\d*$/.test(valor)) {
      throw new Error('Existe un orden de espera inválido.');
    }

    const numero = Number(valor);

    if (!Number.isSafeInteger(numero)) {
      throw new Error('El orden de espera supera el rango permitido.');
    }

    maximoOrden = Math.max(maximoOrden, numero);
  }

  if (!Number.isSafeInteger(maximoOrden + 1)) {
    throw new Error('No es posible asignar otro orden de espera.');
  }

  ordenEspera = maximoOrden + 1;
}

const ahora = new Date().toISOString();
const inscripcionId = `INS-${randomBytes(16).toString('hex')}`;

const registro = {
  inscripcion_id: inscripcionId,
  usuario_id: contexto.datos.usuario_id,
  evento_id: contexto.datos.evento_id,
  estado,
  fecha_inscripcion: ahora,
  fecha_actualizacion: ahora,
  nombre_acreditacion: contexto.datos.nombre_acreditacion,
  observaciones: contexto.datos.observaciones,
  origen: 'WEB',
  orden_espera: ordenEspera,
};

const auditoria = {
  auditoria_id: `AUD-${inscripcionId}-CREATE`,
  inscripcion_id: inscripcionId,
  usuario_id: registro.usuario_id,
  evento_id: registro.evento_id,
  accion: 'CREATE',
  estado_anterior: '',
  estado_nuevo: estado,
  fecha: ahora,
  resultado: 'OK',
  detalle: 'Inscripción creada desde WEB.',
};

return [{
  json: {
    continuar: true,
    registro,
    auditoria,
  },
}];

const preparado = $('Preparar nueva inscripción').first().json;
const items = $input.all();

if (items.length !== 1) {
  throw new Error('La escritura no devolvió un único registro.');
}

const guardado = items[0].json;

// Comprueba que la salida del nodo de escritura corresponde al registro.
for (const [campo, esperado] of Object.entries(preparado.registro)) {
  if (String(guardado[campo] ?? '') !== String(esperado ?? '')) {
    throw new Error('La salida de escritura no coincide con la inscripción.');
  }
}

return [{
  json: preparado.auditoria,
}];

const preparado = $('Preparar nueva inscripción').first().json;
const items = $input.all();

if (items.length !== 1) {
  throw new Error('La escritura no devolvió una única auditoría.');
}

const guardado = items[0].json;

for (const [campo, esperado] of Object.entries(preparado.auditoria)) {
  if (String(guardado[campo] ?? '') !== String(esperado ?? '')) {
    throw new Error('La salida de escritura no coincide con la auditoría.');
  }
}

const registro = preparado.registro;

return [{
  json: {
    respuesta: {
      ok: true,
      mensaje: registro.estado === 'CONFIRMADA'
        ? 'Inscripción confirmada.'
        : 'Inscripción registrada en lista de espera.',
      data: {
        inscripcion_id: registro.inscripcion_id,
        evento_id: registro.evento_id,
        estado: registro.estado,
        fecha_inscripcion: registro.fecha_inscripcion,
        nombre_acreditacion: registro.nombre_acreditacion,
        orden_espera: registro.orden_espera === ''
          ? null
          : registro.orden_espera,
      },
    },
  },
}];

