  throw new Error('Respuesta de autenticación inesperada.');
}

if (autenticacion.status_http !== 200) {
  if (autenticacion.respuesta?.ok !== false) {
    throw new Error('Respuesta de rechazo de autenticación inválida.');
  }

  return [{
    json: {
      continuar: false,
      status_http: autenticacion.status_http,
      respuesta: autenticacion.respuesta,
    },
  }];
}

