  autenticacion.respuesta?.ok !== true ||
  typeof usuario?.usuario_id !== 'string' ||
  !usuario.usuario_id.trim()
) {
  throw new Error('No se recibió un usuario autenticado válido.');
}

// Esta consulta no admite seleccionar otro usuario mediante parámetros.
const solicitud = $('Webhook - Consultar mis inscripciones').first().json;

if (Object.keys(solicitud.query ?? {}).length > 0) {
  return [{
    json: {
      continuar: false,
      status_http: 400,
      respuesta: {
        ok: false,
        error: {
          codigo: 'CONSULTA_INSCRIPCIONES_INVALIDA',
          mensaje: 'Esta consulta no admite parámetros.',
        },
      },
    },
  }];
}

return [{
  json: {
    continuar: true,
    usuario_id: usuario.usuario_id,
  },
}];

